import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第26章 台风","description":"","frontmatter":{},"headers":[],"relativePath":"第26章_台风.md","filePath":"第26章_台风.md"}'),r={name:"第26章_台风.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第26章-台风" tabindex="-1">第26章 台风 <a class="header-anchor" href="#第26章-台风" aria-label="Permalink to &quot;第26章 台风&quot;">​</a></h1><p>十一月来了一场台风。</p><p>前一天下午，学校的广播响了三次。</p><p>第一次说今晚可能有风雨，住校的同学不要外出。第二次说晚自习提前半小时结束。第三次说，明天停课一天，具体安排等通知。</p><p>广播的声音从走廊那头的喇叭里出来，先咳了一下，然后开始念。念到第二次的时候，楼道里已经开始有人跑。</p><p>宿舍里炸了。有人开始打牌，有人翻出泡面，有人把窗户用胶带贴了个叉。</p><p>贴胶带是本地同学的规矩。他们说要斜着贴，贴成米字，风再大玻璃也不会碎。我们宿舍六个人，四个人在贴，还有人负责去接水。</p><p>沈聿站在窗边往外看，说这风不大。</p><p>我说，还没到。</p><p>那天晚上风确实不大。雨下了一夜，一直下到早上。早上六点我醒了一次，窗外全是白的，什么都看不见。楼下那棵树被吹得歪着，叶子贴在地上。</p><p>我们宿舍的窗户贴了胶带，玻璃上横横竖竖好几道。天亮之后看那些胶带，有点像小孩画的画。</p><p>上午雨还在下。我们几个在宿舍里坐着，谁都不出去。有人拿手机给家里打电话，说学校停课了。我也给奶奶打了一个，她说家里没事，让我别乱跑。</p><p>中午雨小了点。我下楼去小卖部买水。</p><p>小卖部在一楼楼梯口旁边，平时人很多，那天几乎没人。我买了两瓶水，出来的时候看到门口站着一个人。</p><p>是她。</p><p>她穿着一件外套，不是校服。头发有点湿，应该是刚从宿舍过来。</p><p>她也看见我了。</p><p>我们两个人在小卖部门口站了两秒。</p><p>我说，你怎么在这。</p><p>她说，买水。</p><p>我说，我也是。</p><p>她说，哦。</p><p>门口的地面积了水，一片一片的。雨还在下，但是很细。</p><p>她说，你回去吗。</p><p>我说，回。</p><p>她说，那你走哪条路。</p><p>我说，东边。</p><p>她说，我也东边。</p><p>我们一起走了。</p><p>从一楼到宿舍楼要走一段露天的路，中间有一小段有顶，是食堂的檐。我们两个人从那一段下面走过去，走得很慢。雨落在檐上，声音很密。</p><p>全程我们没怎么说话。我问她吃早饭没有。她说吃了。然后就没话了。</p><p>走到宿舍楼下面，我们要分开了，她住西楼，我住东楼。</p><p>她停下来说，你等一下。</p><p>她把手伸进外套口袋里，掏出一样东西。</p><p>是一小包饼干。就是小卖部卖的那种，一块五毛钱一个，牌子是蓝白的，包装纸上印着一个笑脸。</p><p>她说，给你。</p><p>我说，为什么。</p><p>她说，刚才买的，买了两包。</p><p>我说，那包呢。</p><p>她说，我吃了。</p><p>我说，你自己留一包不行吗。</p><p>她说，我不爱吃这个。</p><p>我接过来。饼干是硬的，隔着包装纸能摸到边角。</p><p>我说，你是不是把两包都买了。</p><p>她说，没有。</p><p>我说，那这一包哪来的。</p><p>她说，我买了两包，吃了一包。</p><p>我说，你刚才说的是不爱吃。</p><p>她想了一下，说，那是我现在不爱吃了。</p><p>她说，我走了。</p><p>她转身走进雨里。走了几步，她回头说了一句。</p><p>她说，下午要是还下雨，你就在宿舍别出来。</p><p>我说，好。</p><p>她就走了。</p><p>那包饼干我带回宿舍，放在桌子上。沈聿看见，问哪来的。我说买的。他说，你不是刚买了水吗。我说，顺手买的。</p><p>他说，你这人真能睁眼说瞎话。</p><p>那天下午雨又大了。风声从窗户缝里进来，呜呜的。我把那包饼干吃了，一块一块吃的，吃得很慢。饼干有点干，我喝了两口水。</p><p>吃到最后一小块，我把包装袋留着，折起来，夹进了那本本子里。</p><p>夹进去的时候我想起了那张卡。卡在另一本练习册里，纸边已经卷了。</p><p>那时候我发现，我的东西开始变多了。一本本子，一张卡，一个空瓶子，现在又多了一个包装袋。</p><p>都不是什么值钱的东西。加起来值不到十块钱。</p><p>那天晚上她发消息说：饼干好吃吗。</p><p>我说：好吃。</p><p>她说：骗人。</p><p>我说：真的。</p><p>她说：那个饼干很干。</p><p>我说：我还喝了两瓶水。</p><p>她说：你这个人。</p><p>隔了一会儿，她说：今天在楼下，我本来要走别的路。</p><p>我说：那你为什么走东边。</p><p>她说：因为我看见你了。</p><p>那天晚上我想了很久。</p><p>我把那包饼干的事跟她说了一遍。我说你当时口袋里其实还剩一包吧。</p><p>她说：没有。</p><p>我说：那你不饿了。</p><p>她说：我不饿。</p><p>我说：你早上没吃吧。</p><p>她停了一会儿，回了一个字：嗯。</p><p>我说：下次别这样。</p><p>她说：你管我。</p><p>台风天停课，对我们来说是一件好事。因为学校里的规矩到那天就松了一点。平时不能走在一起的人，那天可以在雨里走一段檐下。平时不能说的话，那天可以从口袋里掏出一样东西递过去。</p><p>全校几千个学生都在躲风躲雨。我们两个人在雨里走了一小段路。</p><p>我后来想，这大概就是那时候我们所有的自由：一场台风，一段屋檐，一包一块五的饼干。</p><p>那天晚上我把那句话写在本子上。写完我看着它，又划掉了一半。</p><p>我把“所有的自由”那四个字划掉了，改成了“运气”。</p><p>因为自由是自己能选的，运气不是。那天她从西边走到东边，不是因为她自由。她只是恰好看见了我。</p><p>那场台风后来说还有第二次。第二次来的时候学校已经放假了，我在家，她在她家。</p><p>她在手机上跟我说，外面的树倒了。</p><p>我说，你那边风大吗。</p><p>她说，大。</p><p>我说，你别开窗。</p><p>她说，我就开一会儿。</p><p>我说，别开。</p><p>她说，你管我。</p><p>我说，你就不能听一次。</p><p>她说，那你过来关。</p><p>我说，我过不去。</p><p>她说，那就别管我。</p><p>那是我第一次觉得她说“你管我”的时候，不是炋娇。</p><p>那四个字说得很轻，可它后面藏着东西。她是在说：你能管到的地方就那么多，剩下的我自己来。</p><p>那时候我以为她说的是窗户。</p><p>以后我才知道，她说的是所有的事。</p><p>那包饼干的包装袋一直夹在本子里。包装上印着一个别扭的笑脸，画得很难看，两个眼睛一边大一边小。</p><p>后来那本本子写满了，我换了一本新的。换的时候我把旧的翻了一遍，把包装纸取出来，夹进新本子的第一页。</p>',104)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
